/**
 * @defgroup kernel_message_queue_tests Message Queue
 * @ingroup all_tests
 * @{
 * @}
 */

#include <zephyr/ztest.h>
#include "test_msgq.h"

#ifdef CONFIG_USERSPACE
ZTEST_BMEM struct k_mem_partition_attr_t *attr;
#endif
extern struct k_msgq kmsgq;
extern struct k_msgq msgq;
extern struct k_msgq msgq1;
extern struct k_sem end_sema;
extern struct k_thread tdata;
extern struct k_thread tdata1;
extern struct k_thread tdata2;
K_THREAD_STACK_EXTERN(tstack);
K_THREAD_STACK_EXTERN(tstack1);
K_THREAD_STACK_EXTERN(tstack2);

/*test case main entry*/
void *msgq_setup(void)
{
	k_thread_access_grant(k_current_get(), &kmsgq, &msgq, &msgq1,
			      &end_sema, &tdata, &tdata1, &tdata2,
			      &tstack, &tstack1, &tstack2);
	return NULL;
}

ZTEST_SUITE(msgq_api, NULL, msgq_setup, NULL, NULL, NULL);

ZTEST_SUITE(msgq_api_1cpu, NULL, msgq_setup,
	    ztest_simple_1cpu_before, ztest_simple_1cpu_after, NULL);
